import {validRecord} from './calculations.js';

export function createStorage({onLoad,onClear,onMessage,transport=null}){
  let user=null,revision=0,writing=false,register=false;
  const shell=document.createElement('section');shell.id='auth-screen';shell.innerHTML=`<div class="auth-story"><a class="brand" href="/">forma<span class="dot">●</span></a><p class="eyebrow">SEU HISTÓRICO, COM VOCÊ.</p><h1>Cada fase merece<br>ser lembrada.</h1><p>Suas avaliações guardadas na sua conta.<br>Acompanhe sua evolução em qualquer dispositivo.</p><div class="auth-art"><span>Medidas organizadas</span><span>Evolução visual</span><span>Seu próprio ritmo</span></div></div><div class="auth-card"><div class="auth-mark" aria-hidden="true">↗</div><br><span class="pill">SEU ESPAÇO NO FORMA</span><h2 id="auth-title">Entre na sua conta</h2><p id="auth-intro">Seu próximo passo começa aqui.</p><form id="auth-form"><label>E-mail<input placeholder="voce@exemplo.com" name="email" type="email" autocomplete="username" maxlength="254" required></label><label>Senha<span class="password-wrap"><input placeholder="Sua senha" name="password" type="password" autocomplete="current-password" minlength="12" maxlength="128" required><button type="button" id="password-visibility" aria-label="Mostrar senha" aria-pressed="false">Mostrar</button></span></label><p class="muted" id="password-help">Use uma senha de 12 a 128 caracteres.</p><p id="auth-error" role="alert"></p><button type="submit" class="primary" id="auth-submit">Entrar</button></form><button type="button" class="quiet" id="auth-toggle">Ainda não tenho conta</button><p class="muted auth-footer">Cada conta acessa somente suas próprias avaliações. O e-mail serve como identificador de acesso.</p></div>`;
  document.body.prepend(shell);
  const bar=document.createElement('div');bar.className='account-bar';bar.innerHTML='<span id="account-email"></span><span id="save-status" role="status">Conectando…</span><button class="quiet" id="account-reload">Atualizar dados</button><button class="quiet" id="account-logout">Sair</button>';
  document.querySelector('main').prepend(bar);
  const migration=document.createElement('section');migration.className='migration-banner';migration.hidden=true;migration.innerHTML='<div><strong>Encontramos avaliações antigas neste navegador.</strong><p id="migration-description"></p></div><button class="primary" id="migrate-local">Importar para minha conta</button>';
  bar.after(migration);
  const $=s=>document.querySelector(s);
  async function api(route,options={}){if(transport)return transport(route,options,user);let response;try{response=await fetch(route,{...options,credentials:'same-origin',headers:{'Content-Type':'application/json',...(user?{'X-Forma-User':user.id}:{}),...options.headers}})}catch{throw Error('Não foi possível conectar ao servidor. Confira sua conexão e tente novamente.');}const data=await response.json().catch(()=>({error:'O servidor não retornou uma resposta válida.'}));if(!response.ok)throw Error(data.error||'Não foi possível concluir a operação.');return data;}
  function legacy(){try{const data=JSON.parse(localStorage.getItem('forma.records.v1')||'[]');return Array.isArray(data)&&data.length&&data.every(validRecord)?data:null;}catch{return null}}
  function migrationState(count){const data=legacy();migration.hidden=!data;if(data){$('#migration-description').textContent=`${data.length} avaliação(ões) local(is). ${count?'Sua conta já possui avaliações. Use um backup JSON para revisar e importar manualmente.':'Importe apenas se estes dados forem seus. A cópia local será preservada.'}`;$('#migrate-local').disabled=count>0;}}
  function locked(){document.body.classList.add('signed-out');document.body.classList.remove('session-loading');user=null;revision=0;onClear();}
  async function load(){const currentUser=user;const data=await api('/api/assessments');if(currentUser!==user)return;revision=data.revision;onLoad(data.records);migrationState(data.records.length);$('#account-email').textContent=user.email;$('#save-status').textContent='Dados salvos no servidor';document.body.classList.remove('signed-out','session-loading');}
  $('#password-visibility').onclick=()=>{const input=$('#auth-form').elements.password;const show=input.type==='password';input.type=show?'text':'password';$('#password-visibility').textContent=show?'Ocultar':'Mostrar';$('#password-visibility').setAttribute('aria-label',show?'Ocultar senha':'Mostrar senha');$('#password-visibility').setAttribute('aria-pressed',String(show));};
  $('#auth-toggle').onclick=()=>{register=!register;$('#auth-intro').textContent=register?'Comece a registrar sua evolução, uma medida de cada vez.':'Que bom ter você por aqui. Vamos acompanhar sua evolução?';$('#auth-error').classList.remove('success');$('#auth-title').textContent=register?'Crie sua conta':'Entre na sua conta';$('#auth-submit').textContent=register?'Criar conta':'Entrar';$('#auth-toggle').textContent=register?'Já tenho uma conta':'Ainda não tenho conta';$('#auth-form').elements.password.autocomplete=register?'new-password':'current-password';$('#auth-error').textContent='';};
  $('#auth-form').onsubmit=async event=>{event.preventDefault();$('#auth-submit').disabled=true;$('#auth-submit').textContent='Aguarde…';$('#auth-error').classList.remove('success');$('#auth-error').textContent='';try{const form=event.target;const data=await api(register?'/api/register':'/api/login',{method:'POST',body:JSON.stringify({email:form.elements.email.value,password:form.elements.password.value})});form.elements.password.value='';if(data.pendingConfirmation){$('#auth-error').classList.add('success');$('#auth-error').textContent='Confira seu e-mail e confirme o cadastro antes de entrar.';return;}user=data.user;await load();}catch(error){$('#auth-error').textContent=error.message;}finally{$('#auth-submit').disabled=false;$('#auth-submit').textContent=register?'Criar conta':'Entrar';}};
  $('#account-logout').onclick=async()=>{if(writing)return;try{await api('/api/logout',{method:'POST',body:'{}'});locked();}catch(error){onMessage(error.message);}};
  $('#account-reload').onclick=async()=>{if(writing)return;if(!confirm('Recarregar as avaliações salvas no servidor? Alterações ainda não salvas em um formulário serão descartadas.'))return;try{document.querySelector('#dialog').close();await load();}catch(error){onMessage(error.message);}};
  async function save(records){
    if(!user)throw Error('Entre na sua conta para salvar.');if(writing)throw Error('Aguarde a gravação anterior terminar.');writing=true;$('#save-status').textContent='Salvando…';$('#account-logout').disabled=true;$('#account-reload').disabled=true;
    try{const data=await api('/api/assessments',{method:'PUT',body:JSON.stringify({records,revision})});revision=data.revision;$('#save-status').textContent='Dados salvos no servidor';migrationState(data.records.length);return data.records;}
    catch(error){$('#save-status').textContent='Não salvo — tente novamente';throw error;}
    finally{writing=false;$('#account-logout').disabled=false;$('#account-reload').disabled=false;}
  }
  $('#migrate-local').onclick=async()=>{const data=legacy();if(!data||!confirm(`Importar ${data.length} avaliação(ões) para a conta ${user.email}? Confirme que estes dados são seus.`))return;try{onLoad(await save(data));onMessage('Avaliações importadas para sua conta. A cópia antiga do navegador foi preservada.');}catch(error){onMessage(error.message);}};
  return {save,request:api,async boot(){try{const data=await api('/api/session');$('#auth-toggle').hidden=!data.allowRegistration;if(data.user){user=data.user;await load();}else locked();}catch(error){locked();$('#auth-error').textContent=error.message;}}};
}
